-- create "chat_reports" table
CREATE TABLE "chat_reports" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "reporter_id" uuid NOT NULL, "target_type" character varying NOT NULL, "target_id" character varying NOT NULL, "conversation_id" character varying NOT NULL DEFAULT '', "reported_user_id" uuid NULL, "reason" character varying NOT NULL, "details" character varying NOT NULL DEFAULT '', "block_reported_user" boolean NOT NULL DEFAULT false, "evidence" jsonb NULL, "evidence_selection" character varying NOT NULL DEFAULT '', "evidence_hash" character varying NOT NULL DEFAULT '', "evidence_hash_verified" boolean NOT NULL DEFAULT false, "priority" character varying NOT NULL DEFAULT 'normal', "status" character varying NOT NULL DEFAULT 'open', "sla_due_at" timestamptz NOT NULL, "evidence_retained_until" timestamptz NOT NULL, "legal_hold" boolean NOT NULL DEFAULT false, "spam_score" bigint NULL, "spam_signals" jsonb NOT NULL, "spam_source" character varying NOT NULL DEFAULT '', "decision" jsonb NULL, "reporter_outcome" character varying NOT NULL DEFAULT 'none', "idempotency_key" character varying NULL, "evidence_purged_at" timestamptz NULL, PRIMARY KEY ("id"));
-- create index "chatreport_evidence_retained_until_evidence_purged_at" to table: "chat_reports"
CREATE INDEX "chatreport_evidence_retained_until_evidence_purged_at" ON "chat_reports" ("evidence_retained_until", "evidence_purged_at");
-- create index "chatreport_reported_user_id" to table: "chat_reports"
CREATE INDEX "chatreport_reported_user_id" ON "chat_reports" ("reported_user_id");
-- create index "chatreport_reporter_id_created_at" to table: "chat_reports"
CREATE INDEX "chatreport_reporter_id_created_at" ON "chat_reports" ("reporter_id", "created_at");
-- create index "chatreport_reporter_id_idempotency_key" to table: "chat_reports"
CREATE UNIQUE INDEX "chatreport_reporter_id_idempotency_key" ON "chat_reports" ("reporter_id", "idempotency_key");
-- create index "chatreport_status_priority_sla_due_at" to table: "chat_reports"
CREATE INDEX "chatreport_status_priority_sla_due_at" ON "chat_reports" ("status", "priority", "sla_due_at");
-- create "evidence_retention_settings" table
CREATE TABLE "evidence_retention_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "retention_days" bigint NOT NULL DEFAULT 180, "legal_hold_days" bigint NOT NULL DEFAULT 730, "updated_by" character varying NOT NULL DEFAULT '', "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create "outbox_events" table
CREATE TABLE "outbox_events" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "event_type" character varying NOT NULL, "subject" character varying NOT NULL, "payload" jsonb NOT NULL, "published_at" timestamptz NULL, PRIMARY KEY ("id"));
-- create index "outboxevent_published_at_created_at" to table: "outbox_events"
CREATE INDEX "outboxevent_published_at_created_at" ON "outbox_events" ("published_at", "created_at");
-- create "suspension_cases" table
CREATE TABLE "suspension_cases" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "source" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'pending', "risk_score" bigint NOT NULL, "top_signals" jsonb NOT NULL, "report_count" bigint NOT NULL DEFAULT 0, "signals" jsonb NULL, "evidence" jsonb NULL, "reports" jsonb NULL, "model_version" character varying NOT NULL DEFAULT '', "external_reference" character varying NULL, "decision" jsonb NULL, "escalated" boolean NOT NULL DEFAULT false, PRIMARY KEY ("id"));
-- create index "suspensioncase_account_id" to table: "suspension_cases"
CREATE INDEX "suspensioncase_account_id" ON "suspension_cases" ("account_id");
-- create index "suspensioncase_external_reference" to table: "suspension_cases"
CREATE UNIQUE INDEX "suspensioncase_external_reference" ON "suspension_cases" ("external_reference");
-- create index "suspensioncase_status_risk_score" to table: "suspension_cases"
CREATE INDEX "suspensioncase_status_risk_score" ON "suspension_cases" ("status", "risk_score");
